class Solution {
    public boolean canSpell(String sign, String tiles) {
        char[] pool = tiles.toCharArray();
        for (char ch : sign.toCharArray()) {
            int at = -1;
            for (int i = 0; i < pool.length && at < 0; i++) if (pool[i] == ch) at = i;
            if (at < 0) return false;
            pool[at] = '#';
        }
        return true;
    }
}

