class Solution {
public:
    bool canSpell(string& sign, string& tiles) {
        string pool = tiles;
        for (char ch : sign) {
            size_t at = pool.find(ch);
            if (at == string::npos) return false;
            pool[at] = '#';
        }
        return true;
    }
};

