bool canSpell(char* sign, char* tiles) {
    size_t t = strlen(tiles);
    char* pool = malloc(t + 1);
    memcpy(pool, tiles, t + 1);
    bool ok = true;
    for (char* p = sign; *p && ok; p++) {
        char* at = strchr(pool, *p);
        if (!at) ok = false;
        else *at = '#';
    }
    free(pool);
    return ok;
}

