class Solution:
    def canSpell(self, sign: str, tiles: str) -> bool:
        s, t = sorted(sign), sorted(tiles)
        j = 0
        for ch in s:
            while j < len(t) and t[j] < ch:
                j += 1
            if j == len(t) or t[j] != ch:
                return False
            j += 1
        return True

