        Arrays.sort(s);
        Arrays.sort(t);
        int j = 0;
        for (char ch : s) {
            while (j < t.length && t[j] < ch) j++;
            if (j == t.length || t[j] != ch) return false;
            j++;
        }
        return true;
    }
}

