static int cmpChar(const void* a, const void* b) {
    return *(const char*) a - *(const char*) b;
}

bool canSpell(char* sign, char* tiles) {
    size_t n = strlen(sign), m = strlen(tiles);
    char* s = malloc(n + 1);
    char* t = malloc(m + 1);
    memcpy(s, sign, n + 1);
    memcpy(t, tiles, m + 1);
    qsort(s, n, 1, cmpChar);
    qsort(t, m, 1, cmpChar);
    size_t j = 0;
    bool ok = true;
    for (size_t i = 0; i < n && ok; i++) {
        while (j < m && t[j] < s[i]) j++;
        if (j == m || t[j] != s[i]) ok = false;
        else j++;
    }
    free(s);
    free(t);
    return ok;
}

