class Solution:
    def canSpell(self, sign: str, tiles: str) -> bool:
        have = [0] * 26
        for ch in tiles:
            have[ord(ch) - ord('a')] += 1
        for ch in sign:
            k = ord(ch) - ord('a')
            have[k] -= 1
            if have[k] < 0:
                return False
        return True

