class Solution {
    public boolean canSpell(String sign, String tiles) {
        int[] have = new int[26];
        for (char ch : tiles.toCharArray()) have[ch - 'a']++;
        for (char ch : sign.toCharArray()) {
            if (--have[ch - 'a'] < 0) return false;
        }
        return true;
    }
}

